"""A Class for interacting with the Functional Keypad (FKP) for core functionality such as performing gantry ASU
and starting beam delivery, using the Functional Keypad Interface (FKPID) drivers. Alternatively, the Crowbar
software test tool can be used for performing the equivalent functionality when an FKP is not available."""

from interops.libraries.integrity.linac import Linac
import interops.libraries.integrity.test_tools.crowbar as test_tool_cb
import interops.libraries.integrity.test_tools.fkid_test_harness as test_tool_fkidth
import interops.libraries.miscellaneous.message_dialog_popups as msg_popup
from interops.libraries.miscellaneous.registry_functions import match_value_under_registry_subkey
from interops.libraries.desktop.application import ApplicationManager
from interops.libraries.desktop.configuration import Config
import interops.libraries.desktop.config_constants as cfg
import urllib.request
import logging
import win32com.client
import os
import sys

# Get the current python installation path
python_install_path = sys.exec_prefix
sharedconfig_path = os.path.abspath(os.path.join(
    python_install_path, cfg.DEFAULT_SHAREDCONFIG_PATH))
# Load the sharedconfig.cfg file
Config.load(sharedconfig_path)

import squishtest3 as sq

logger = logging.getLogger(__name__)

# FKPID API FOUND HERE
# http://gbcsvalm01:49158/svn/Autotest//trunk/src/FkpInterfaceDeviceControl/IFkpInterfaceDeviceController.cs/?p=2767


class Linac_fkp():
    '''NB pywin32 must be installed for headless fkpid to work - included in dependencies 2.2'''

    def __init__(self, linacObj=0):

        use_headless_fkpid = Config.get_as_bool("run_config.use_headless_fkpid")
        '''this is the config setting for the headless fkpid'''
        use_http_fkpid = Config.get_as_bool("run_config.use_remote_fkpid")
        http_prefix = "http://127.0.0.1:6804/?command="

        # try and connect to http fkpid
        # this is the fkpid running within a web service
        # otherwise connect directly to fkpid using com

        if use_http_fkpid:
            try:
                logger.info("Connecting to http fkpid")
                self.http_prefix = http_prefix
                urllib.request.urlopen(http_prefix + "connected").read()
                self.use_http_fkpid = True
                self.use_headless_fkpid = False
                logger.info("Successfully connected to http fkpid")
            except Exception as e:
                logger.info("Error connecting to http fkpid: " + str(e))

        else:

            try:
                logger.info("Connecting to fkpid com interface")
                logger.info("Successfully imported win32com.client for fkpid com interface")
                self.use_headless_fkpid = True
                self.use_http_fkpid = False
            except Exception as e:
                logger.info("win32com.client exception, using fkpid GUI" + str(e))
                self.use_headless_fkpid = False

        # self.linac=Linac()
        if linacObj == 0:
            self.linac = Linac()
        else:
            self.linac = linacObj
        '''look in config for remote fkpid connection
            this is the config setting for connecting to a fkpid remotely - ie not local
        '''
        if self.linac.demonstrator: #type: ignore
            logger.info("Crowbar - Initiate")
            ip_addr = Config.get("attach.host")
            self.crowbar = test_tool_cb.Crowbar(hostAddress=ip_addr)
            return

        use_remote_fkpid = Config.get("attach.fkpid_host")
        show_fkpid_popup_prompts = Config.get_as_bool("run_config.show_fkpid_popup_prompts")

        if use_remote_fkpid or self.use_http_fkpid or self.use_headless_fkpid:
            self.linac.demonstrator = False #type: ignore

        if not self.linac.demonstrator: #type: ignore
            if self.use_headless_fkpid:
                '''connect and authorise FKPID via COM'''
                self.fkpid_com = win32com.client.Dispatch(
                    "Elekta.RT.Linac.AutomatedSetup.FkpInterfaceDeviceController")
                logger.info("FKPID via COM Dispatched FkpInterfaceDeviceController")
                if show_fkpid_popup_prompts:
                    msg_popup.show_html_dialog(
                        os.path.join(os.path.dirname(__file__), "test_tools/fkpid_popup_dialogs/connect_FKPID_dialogbox2.htm"), height=575, width=575)
                self.fkpid_com.FindDevice()
                logger.info("FKPID via COM FindDevice done")
                if not self.fkpid_com.Connected:
                    logger.info("FKPID via COM Not Connected")
                    if show_fkpid_popup_prompts:
                        msg_popup.show_html_dialog(
                            os.path.join(os.path.dirname(__file__), "test_tools/fkpid_popup_dialogs/connect_FKPID_dialogbox2.htm"), height=575, width=575)
                    self.fkpid_com.Disconnect()
                    self.fkpid_com.FindDevice()
                self.fkpid_com.StartWatchdogResetTimer()
                logger.info("FKPID via COM Watchdog reset timer started")
                self.fkpid_com.Authorize(True)
                logger.info("FKPID via COM Authorised")
                sq.snooze(2)
                if show_fkpid_popup_prompts:
                    msg_popup.show_html_dialog(os.path.join(os.path.dirname(__file__),
                                                            "test_tools/fkpid_popup_dialogs/enable_FKPID_dialogbox2.htm"), height=900, width=900)
                return
            elif self.use_http_fkpid:
                try:
                    urllib.request.urlopen(self.http_prefix + "connected").read()
                    logger.info("FKPID via HTTP connected")
                    return
                except Exception:
                    logger.info("FKPID via COM failed to connect")
                    self.use_http_fkpid = False

            if not use_remote_fkpid:
                # Check whether FKPID drivers are installed, see registry entry
                subkey = r"SYSTEM\ControlSet001\Control\Class\{36FC9E60-C465-11CF-8056-444553540000}"
                value_name = "ProviderName"
                expectedvalue = "FTDI"
                reg_entry = match_value_under_registry_subkey(
                    subkey, value_name, expectedvalue, hive='HLM')
                if type(reg_entry) == str:
                    fkpid_is_installed = reg_entry.strip('\n') == "True"
                if not fkpid_is_installed:
                    logger.info("FKPID drivers not installed")
                    msg_popup.showMsg("Warning", "Test will be aborted - no FKPID drivers installed")
                    return False
                logger.info("FKPID drivers installed")
            # try to attach to already running FKPID
            try:
                logger.info("Attaching to FKPID TestHarness application")
                if not ApplicationManager.is_application_running("TestHarness"):
                    if use_remote_fkpid:
                        sq.attachToApplication("TestHarness", use_remote_fkpid)
                    else:
                        sq.attachToApplication("TestHarness")
                self.fkpid = test_tool_fkidth.FkidTh()
                self.fkpid.ready()
                logger.info("FKPID TestHarness application ready done")
            except Exception:
                logger.info("Problem attaching to FKPID TestHarness application - retry")
                if show_fkpid_popup_prompts:
                    # Html dialog for FKPID connection test
                    dialog_path = os.path.join(os.path.dirname(__file__), "test_tools/fkpid_popup_dialogs/connect_FKPID_dialogbox2.htm")
                    msg_popup.show_html_dialog(dialog_path, height=575, width=575)
                #FKPID - connect, authorise, enable_bit
                self.fkpid = test_tool_fkidth.FkidTh()
                self.fkpid.ready()
                logger.info("FKPID TestHarness application ready done")

            properties = sq.object.properties(self.fkpid.chk_reset_timer)
            if properties['checked'] == False:
                try:
                    self.fkpid.initialise_fkpid()
                    logger.info("initialise fkpid done")
                except Exception:
                    logger.info("problem initialising fkpid")
                    if show_fkpid_popup_prompts:
                        msg_popup.show_html_dialog(
                            os.path.join(os.path.dirname(__file__), "test_tools/fkpid_popup_dialogs/initialise_FKPID_failed_dialogbox2.htm"), height=680, width=850)

                if show_fkpid_popup_prompts:
                    # instruct user to enable FKPID.
                    msg_popup.show_html_dialog(os.path.join(os.path.dirname(__file__), "test_tools/fkpid_popup_dialogs/enable_FKPID_dialogbox2.htm"), height=900, width=900)

    def start_beam(self):

        if self.linac.demonstrator: #type: ignore
            logger.info("Crowbar - start beam")
            self.crowbar.start_beam()

        elif self.use_headless_fkpid:
            logger.info("FKPID COM - StartMegavoltageRadiation")
            self.fkpid_com.StartMegavoltageRadiation(True, 100)

        elif self.use_http_fkpid:
            logger.info("FKPID HTTP - start beam")
            urllib.request.urlopen(self.http_prefix + "start").read()

        else:
            logger.info("FKPID TestHarness start beam")
            self.fkpid.start_beam()

    def interrupt_beam(self):
        if self.linac.demonstrator: #type: ignore
            logger.info("Crowbar - interrupt beam")
            self.crowbar.interrupt_beam()

        elif self.use_headless_fkpid:
            logger.info("FKPID COM - InterruptMegavoltageRadiation")
            self.fkpid_com.InterruptMegavoltageRadiation(True, 100)

        elif self.use_http_fkpid:
            logger.info("FKPID HTTP - interrupt beam")
            urllib.request.urlopen(self.http_prefix + "interrupt").read()

        else:
            logger.info("FKPID TestHarness interrupt beam")
            self.fkpid.interrupt_beam()

    def press_reset(self):
        if self.linac.demonstrator: #type: ignore
            logger.info("Crowbar - reset linac")
            self.crowbar.reset_keys()
        else:
            self.fkpid.error_reset() #type: ignore

    def start_beam_after_interupt(self):

        if self.linac.demonstrator: #type: ignore
            logger.info("Crowbar - start beam after interrupt")
            self.crowbar.start_beam()
            sq.snooze(1)
            self.crowbar.start_beam()

        elif self.use_headless_fkpid:
            logger.info("FKPID COM - StartMegavoltageRadiation after interrupt")
            self.fkpid_com.StartMegavoltageRadiation(True, 500)

        elif self.use_http_fkpid:
            logger.info("FKPID HTTP - start beam after interrupt")
            urllib.request.urlopen(self.http_prefix + "start").read()

        else:
            logger.info("FKPID TestHarness start beam after interrupt")
            self.fkpid.start_beam()

    def press_terminate(self):
        if self.linac.demonstrator: #type: ignore
            logger.info("Crowbar - terminate beam")
            self.crowbar.terminate_beam()

        elif self.use_headless_fkpid:
            logger.info("FKPID COM - StopMegavoltageRadiation")
            self.fkpid_com.StartMegavoltageRadiation(False, 500)

        elif self.use_http_fkpid:
            logger.info("FKPID HTTP - stop beam")
            urllib.request.urlopen(self.http_prefix + "stop").read()

        else:
            logger.info("FKPID TestHarness stop beam not implemented")

    def start_asu(self):
        if self.linac.demonstrator: #type: ignore
            logger.info("Crowbar - ASU Start")
            self.crowbar.initiate_gantry_asu()

        elif self.use_headless_fkpid:
            logger.info("FKPID COM - ASU ON")
            self.fkpid_com.EnableAsu(False)
            sq.snooze(1)
            self.fkpid_com.EnableAsu(True)
            sq.snooze(1)
            self.fkpid_com.EnableLinacAsu(True)

        elif self.use_http_fkpid:
            logger.info("FKPID HTTP - ASU ON")
            urllib.request.urlopen(self.http_prefix + "asu_start").read()
        else:
            logger.info("FKPID TEST HARNESS - ASU ON")
            self.fkpid.asu_gantry()

    def stop_asu(self):
        if self.linac.demonstrator: #type: ignore
            logger.info("Crowbar - ASU STOP")
            self.crowbar.disengage_gantry_asu()

        elif self.use_headless_fkpid:
            logger.info("FKPID COM - ASU STOP")
            self.fkpid_com.EnableLinacAsu(False)
            sq.snooze(1)
            self.fkpid_com.EnableAsu(False)

        elif self.use_http_fkpid:
            logger.info("FKPID HTTP - ASU STOP")
            urllib.request.urlopen(self.http_prefix + "asu_stop").read()
        else:
            logger.info("FKPID TEST HARNESS - ASU STOP")
            self.fkpid.disable_asu()

    def move_table_vertical(self, sliderDirection: str = "down", sliderShiftValue: int = 4, dragDuration: int = 2) -> None:
        '''
        Checks if the target test system is an emulator (demonstrator)/ virtual test environment and uses Crowbar
        to move the table vertical by dragging the height slider in the specified direction (up or down) for the specified
        time duration (in seconds).

        If the target test system is not an emulator (i.e. a shelter machine), it will log a message indicating that the
        table height cannot be moved using the FKPID.

        This function is intended to be used by the _set_table_vertical_with_crowbar() function in the
        treatment_setup_delivery_funcs.py module in the Integrity library, where it is used together with the iCOM Vx object
        to read the current actual table vertical position.

        Args:
            sliderDirection (str): The direction to move the table vertical. Can be "up" or "down".
            sliderShiftValue (int): The amount to shift the slider in pixels. The higher the number the faster the table shift.
            dragDuration (int): The duration to drag the slider in seconds.
        Returns:
            None
        '''
        if self.linac.demonstrator: #type: ignore
            # Crowbar will be used to move the table for emulators/ virtual test environments
            logger.info("Crowbar - set table vertical using the Height slider in the User Interface Module (UIM) section")
            self.crowbar.drag_uim_table_height_slider(sliderDirection, sliderShiftValue, dragDuration)
        else:
            # At this time it is unknown if the FKPID driver supports moving the table vertical
            logger.info("Set Table vertical is not currently supported by the FKPID")

