    def check_fkpid_status(self):

        if self.use_headless_fkpid:
            logger.info("FKPID COM - CHECKING STATE")
            sq.snooze(1)
            logger.info("FKPID CONNECTED?: " + str(self.fkpid_com.Connected))
            logger.info("FKPID STATE IS?: " + str(self.fkpid_com.GetState()))

            if "8" not in str(self.fkpid_com.GetState()):
                raise

        elif self.use_http_fkpid:
            logger.info("FKPID COM - CHECKING STATE")
            sq.snooze(1)
            try:
                fkpid_connect = urllib.request.urlopen(self.http_prefix + "connected").readlines()[4]
                logger.info("FKPID CONNECTED?: " + str(fkpid_connect))
            except Exception as e:
                fkpid_connect = urllib.request.urlopen(self.http_prefix + "connected").readlines()
                logger.info("FKPID CONNECTED?: " + str(fkpid_connect))

            try:
                fkpid_state = urllib.request.urlopen(self.http_prefix + "check_fkpid_state").readlines()[4]
                logger.info("FKPID STATE IS?: " + str(fkpid_state))
            except Exception as e:
                fkpid_state = urllib.request.urlopen(self.http_prefix + "check_fkpid_state").readlines()
                logger.info("FKPID STATE IS?: " + str(fkpid_state))

            if "8" not in fkpid_state:
                logger.info("FKPID not in state level 8 will throw exception")
                # raise
        else:
            logger.info("FKPID STATUS CHECK ONLY IMPEMENTED FOR COM")

    def deauthorize_and_disconnect(self):

        if self.linac.demonstrator: #type: ignore
            logger.info("Deauthorize_and_disconnect not implemented for Crowbar")

        elif self.use_headless_fkpid:
            logger.info("FKPID COM - DEAUTHORIZE")
            self.fkpid_com.Authorize(False)
            self.fkpid_com.Disconnect()

        elif self.use_http_fkpid:
            logger.info("FKPID HTTP - DEAUTHORIZE")
            urllib.request.urlopen(self.http_prefix + "deauthorize").read()
            urllib.request.urlopen(self.http_prefix + "disconnect").read()
        else:
            logger.info("FKPID TEST HARNESS -DEAUTHORIZE")
            logger.info("not implemented for testharness")
